import manifest from "@/content/blog/manifest.json";
import posts from "@/content/blog/posts.json";

// Reads the imported My Newsletter archive (content/blog/, generated by
// scripts/import-blog.mjs). Bundled via ES imports — no runtime filesystem
// access, so it works on the Cloudflare Workers runtime where these pages
// render.

export type PostMeta = {
  slug: string;
  title: string;
  subtitle: string;
  date: string; // YYYY-MM-DD
  canonical: string;
  cover: string | null;
};

export type Post = PostMeta & { bodyHtml: string };

const postsMap = posts as Record<string, Post>;

export function getAllPosts(): PostMeta[] {
  return manifest as PostMeta[];
}

export function getPost(slug: string): Post | null {
  return postsMap[slug] ?? null;
}

// "May 8, 2026" — parsed in UTC so the date doesn't drift by timezone.
export function formatDate(iso: string): string {
  const [y, m, d] = iso.split("-").map(Number);
  return new Date(Date.UTC(y, m - 1, d)).toLocaleDateString("en-US", {
    year: "numeric",
    month: "long",
    day: "numeric",
    timeZone: "UTC",
  });
}

// "May 8" — short form for the table's right column.
export function formatShortDate(iso: string): string {
  const [y, m, d] = iso.split("-").map(Number);
  return new Date(Date.UTC(y, m - 1, d)).toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    timeZone: "UTC",
  });
}
